query PanelVariantDetails($v000: String!, $v001: String!, $v002: String!, $v003: String!, $v004: String!, $v005: String!, $v006: String!, $v007: String!) {
  v000: variant(variantId: $v000, dataset: gnomad_r4) { ...PanelVariantFields }
  v001: variant(variantId: $v001, dataset: gnomad_r4) { ...PanelVariantFields }
  v002: variant(variantId: $v002, dataset: gnomad_r4) { ...PanelVariantFields }
  v003: variant(variantId: $v003, dataset: gnomad_r4) { ...PanelVariantFields }
  v004: variant(variantId: $v004, dataset: gnomad_r4) { ...PanelVariantFields }
  v005: variant(variantId: $v005, dataset: gnomad_r4) { ...PanelVariantFields }
  v006: variant(variantId: $v006, dataset: gnomad_r4) { ...PanelVariantFields }
  v007: variant(variantId: $v007, dataset: gnomad_r4) { ...PanelVariantFields }
}
fragment PanelVariantFields on VariantDetails {
  variant_id
  reference_genome
  chrom
  pos
  ref
  alt
  caid
  rsids
  flags
  exome {
    ac an af homozygote_count hemizygote_count filters flags
    faf95 { popmax_population popmax }
    populations { id ac an homozygote_count hemizygote_count }
  }
  genome {
    ac an af homozygote_count hemizygote_count filters flags
    faf95 { popmax_population popmax }
    populations { id ac an homozygote_count hemizygote_count }
  }
  joint {
    ac an homozygote_count hemizygote_count filters
    faf95 { popmax_population popmax }
    populations { id ac an homozygote_count hemizygote_count }
  }
}
